// Generic Template for retrieving any locale facet
template <typename FacetType>
const FacetType& get_facet(const std::locale& loc) {
    // std::use_facet handles type safety and retrieval
    return std::use_facet<FacetType>(loc);
}

// Example Usage: Retrieve the time_get facet
std::locale current_loc("de_DE");

// FacetType specified explicitly
const std::time_get<char>& time_info = 
    get_facet<std::time_get<char>>(current_loc);

// Using the retrieved facet
std::string month_name = time_info.month_name(
    {nullptr, nullptr}, 1);
